class Solution {
public:
    vector<vector<int>> insert(vector<vector<int>>& intervals, vector<int>& newInterval) {
        vector<vector<int>> res;
        int i = 0, n = (int)intervals.size();
        int newL = newInterval[0], newR = newInterval[1];   // 待插入区间的左右端
        // 第一段：完全在 newInterval 左侧（右端 < newL）的区间原样收下
        while (i < n && intervals[i][1] < newL)
            res.push_back(intervals[i++]);
        // 第二段：所有与 newInterval 相交的区间都被它吸收（相交 = 非相离）
        while (i < n && intervals[i][0] <= newR) {
            newL = min(newL, intervals[i][0]);   // 左端向更小处扩展
            newR = max(newR, intervals[i][1]);   // 右端向更大处扩展
            ++i;
        }
        res.push_back({newL, newR});   // 吸收完成，放入合并后的新区间
        // 第三段：剩余区间完全在右侧，原样追加即可保持有序无重叠
        while (i < n)
            res.push_back(intervals[i++]);
        return res;
    }
};

