class Solution {
    public int findMinArrowShots(int[][] points) {
        // 按右端点排序：右端最小的气球决定当前一箭的最优射点
        // 用 Integer.compare 而不是相减，防止坐标为 -2^31 时整型溢出
        Arrays.sort(points, (a, b) -> Integer.compare(a[1], b[1]));
        int arrows = 0;
        long arrowX = 0;            // 上一支箭的射出位置
        boolean hasArrow = false;
        for (int[] p : points) {
            // 气球起点严格大于上一箭位置 => 上一支箭够不到它，必须再射一支
            if (!hasArrow || p[0] > arrowX) {
                arrows++;
                arrowX = p[1];      // 新箭射在当前气球右端
                hasArrow = true;
            }
            // p[0] == arrowX 时端点相接也算命中，不需要新箭
        }
        return arrows;
    }
}

