/**
 * @param {number[][]} points
 * @return {number}
 */
var findMinArrowShots = function (points) {
  // 按右端点排序：右端最小的气球决定当前一箭的最优射点
  points.sort((a, b) => a[1] - b[1]);
  let arrows = 0;
  let arrowX = null;    // 上一支箭的射出位置
  for (const [start, end] of points) {
    // 气球起点严格大于上一箭位置 => 上一支箭够不到它，必须再射一支
    if (arrowX === null || start > arrowX) {
      arrows++;
      arrowX = end;     // 新箭射在当前气球右端，能带走的后续气球最多
    }
    // start === arrowX 时端点相接也算命中，不需要新箭
  }
  return arrows;
};

