func findMinArrowShots(points [][]int) int {
	// 按右端点排序：右端最小的气球决定当前一箭的最优射点
	sort.Slice(points, func(i, j int) bool {
		return points[i][1] < points[j][1]
	})
	arrows := 0
	var arrowX int    // 上一支箭的射出位置
	hasArrow := false
	for _, p := range points {
		// 气球起点严格大于上一箭位置 => 上一支箭够不到它，必须再射一支
		if !hasArrow || p[0] > arrowX {
			arrows++
			arrowX = p[1] // 新箭射在当前气球右端，能带走的后续气球最多
			hasArrow = true
		}
		// p[0] == arrowX 时端点相接也算命中，不需要新箭
	}
	return arrows
}
